//! Turkish Morphology engine.

/// The Zemberek root lexicon (one entry per line), embedded once and shared by every
/// component that reads it. Generated by `scripts/build_full_lexicon.py`.
///
/// The style auditor's AI-text detector does not read it: it keeps the lexicon it was trained
/// with (`data/ai_detector/lexicon.txt.zz`), so this file can change without retraining.
pub(crate) static ZEMBEREK_LEXICON: &str = include_str!("zemberek_lexicon.txt");

